    DENIED("denied"),
    BUSY("busy"),
    UNAVAILABLE("unavailable"),
    FAILED("failed"),
    NOT_RUNNING("notRunning"),
}

/** The events of "ar": what the plugin sends the app. Any thread. */
class AREvents(private val channel: PluginEmit) {
    /** The tracking quality; the first event of a session. */
    fun tracking(state: TrackingState, reason: TrackingReason? = null) {
        val w = PackedWriter()
        w.beginObject()
        w.key("state"); w.string(state.wire)
        reason?.let { v -> w.key("reason"); w.string(v.wire) }
        w.end()
        this.channel.emit("tracking", w.bytes())
    }

    /**
     * A detected plane: added, moved / grown (throttled: a change over 1 cm, at most 10 per second),
     * or gone (`mergedInto` = the plane that absorbed it, ARCore). `pose` = the plane's centre, its
     * Y the normal; `extent` = [width, height] metres; `polygon` = the boundary as x,z pairs in the
     * plane's space.
     */
    fun plane(change: PlaneChange, id: Double, type: PlaneType, pose: Pose, extent: List<Double>, polygon: List<Double>, mergedInto: Double? = null) {
        val w = PackedWriter()
        w.beginObject()
        w.key("change"); w.string(change.wire)
        w.key("id"); w.f64(id)
        w.key("type"); w.string(type.wire)
        w.key("pose"); pose.write(w)
        w.key("extent")
        w.beginArray()
        for (v0 in extent) { w.f64(v0) }
        w.end()
        w.key("polygon")
        w.beginArray()
        for (v0 in polygon) { w.f64(v0) }
        w.end()
        mergedInto?.let { v -> w.key("mergedInto"); w.f64(v) }
        w.end()
        this.channel.emit("plane", w.bytes())
    }

    /**
     * An image target found, lost, or its size refined. While tracked its entity is driven: a rigid
     * pose in metres, no scale — the image's centre, Y out of it, the image in XZ (X along its width,
     * Z towards its bottom). `extent` = [width, height] metres, the framework's estimate (sent again
     * when it changes by a millimetre, at most 10 per second); the last one when lost. A QR target's
     * comes the same way (its frame: X along the symbol's top edge), `extent` = [size, size].
     */
    fun image(entity: Entity, tracked: Boolean, extent: List<Double>) {
        val w = PackedWriter()
        w.beginObject()
        w.key("entity"); entity.write(w)
        w.key("tracked"); w.bool(tracked)
        w.key("extent")
        w.beginArray()
        for (v0 in extent) { w.f64(v0) }
        w.end()
        w.end()
        this.channel.emit("image", w.bytes())
    }

    /** An anchor made by `anchor()` lost or regained after a relocalization. */
    fun anchor(entity: Entity, tracked: Boolean) {
        val w = PackedWriter()
        w.beginObject()
        w.key("entity"); entity.write(w)
        w.key("tracked"); w.bool(tracked)
        w.end()
        this.channel.emit("anchor", w.bytes())
    }

    /**
     * The estimated light (`lightEstimation`): lumens-ish ambient intensity (1000 = ARKit's
     * neutral), colour temperature in kelvin; at most 10 per second.
     */
    fun light(intensity: Double, temperature: Double) {
        val w = PackedWriter()
        w.beginObject()
        w.key("intensity"); w.f64(intensity)
        w.key("temperature"); w.f64(temperature)
        w.end()
        this.channel.emit("light", w.bytes())
    }

    /**
     * The session failed and is over: "unavailable" (no ARKit / ARCore support, ARCore not
     * installed and declined), "camera" (the camera could not be used), "failed".
     */
    fun error(code: ARErrorCode, message: String) {
        val w = PackedWriter()
        w.beginObject()
        w.key("code"); w.string(code.wire)
        w.key("message"); w.string(message)
        w.end()
        this.channel.emit("error", w.bytes())
    }

    /**
     * The session is over, and not by `stop()`: the user left it ("user" — the browser's back / exit
     * of an immersive WebXR session) or the system took it ("system"). Not an error: ARScene closes
     * the scene. ARKit and ARCore never end a session by themselves (an interruption is `tracking`
     * limited): the native halves do not send it.
