/**
 * The service "ar".
 *
 * What the plugin implements. A call arrives on the main thread; its reply is settled exactly
 * once, now or later.
 */
interface ARPlugin {
    /**
     * Start tracking; resolves at the first frame. A second start rejects "busy".
     * Needs the camera permission: asked by the glue before the call, DENIED when refused.
     * Rejects with DENIED / BUSY / UNAVAILABLE / FAILED.
     */
    fun start(options: StartOptions?, reply: Reply<Unit, ARCode>)

    /**
     * Stop tracking: the camera is released, the scene's projection and background cleared. Not
     * running is not an error.
     */
    fun stop(reply: Reply<Unit, ARCode>)

    /**
     * Replace the set of image targets of a RUNNING session without restarting it (the tracking, the
     * planes and the anchors stay); an image no longer in the set stops driving its entity (its
     * `image` event says `tracked: false` once if it was tracked). Before `start`, the images are
     * `StartOptions.images`.
     * Rejects with NOT_RUNNING / FAILED.
     */
    fun setImages(images: List<ImageTarget>, reply: Reply<Unit, ARCode>)

    /**
     * The twin of `setImages` for QR codes: replace the set of QR targets of a RUNNING session
     * without restarting it; a code no longer in the set stops driving its entity (`tracked: false`
     * once if it was tracked). Before `start`, the codes are `StartOptions.codes`. A half that tracks
     * no codes yet (the native ones) rejects "failed".
     * Rejects with NOT_RUNNING / FAILED.
     */
    fun setCodes(codes: List<QRTarget>, reply: Reply<Unit, ARCode>)

    /**
     * What is under a point of the scene's view — in its touches' space (a scene touch's `clientX` /
     * `clientY`: the units of the gl facade's viewport) — nearest first. Empty when nothing is, or on
     * a host without surfaces (the web).
     * Rejects with NOT_RUNNING.
     */
    fun hitTest(x: Double, y: Double, target: HitTarget?, reply: Reply<List<HitResult>, ARCode>)

    /**
     * Pin `entity` to `pose`: the host's anchor drives its matrix from now on (and keeps it true
     * as the world map refines).
     * Rejects with NOT_RUNNING.
     */
    fun anchor(entity: Entity, pose: Pose, reply: Reply<Unit, ARCode>)

    /** Stop driving `entity` (its matrix stays where it was). */
    fun release(entity: Entity, reply: Reply<Unit, ARCode>)

    /**
     * The latest camera frame as a JPEG (the raw image, not the composite — that is
     * `Scene.capture()`).
     * Rejects with NOT_RUNNING / FAILED.
     */
    fun captureFrame(reply: Reply<PluginFile, ARCode>)

    /** The session closed (the app's close, the world's teardown): stop what it started. */
    fun close() {}
}

object ARChannel {
    /** What the halves register under. */
    const val NAME = "ar"

    /** The contract's version: the highest `@since` of its members. */
    const val VERSION = 2

    /** Register the service: `make` builds one session from its params. It must be cheap — no
     *  prompt, no I/O: that belongs to the first call that needs it. */
    fun register(engine: LecodesEngine, make: (params: ARParams, events: AREvents) -> ARPlugin) {
        engine.registerService(NAME, VERSION) { params, channel ->
            val plugin = make(ARParams.read(Wire.reader(params)) ?: ARParams(), AREvents { event, packed -> channel.emitPacked(event, packed) })
            Services.Instance(onCall = { call -> ARGlue.call(plugin, engine.permissions, call.method, call.reader(), call) }, onClose = { plugin.close() })
        }
    }
}

/** Reads a call off the wire and hands it to the plugin; a malformed call never reaches it. */
internal object ARGlue {
    fun call(plugin: ARPlugin, permissions: Permissions, method: String, r: PackedReader, settle: ChannelSettle) {
        val n = r.beginArray()   // the arguments, in their order
        when (method) {
            "start" -> {
                val a0 = if (0 < n && !r.isNull()) (StartOptions.read(r) ?: return settle.reject("bad arguments — AR.start: options")) else { if (0 < n) r.skip(); null }
                val reply = Reply<Unit, ARCode>(settle, null)
                permissions.ensure(listOf(Permissions.Kind.CAMERA)) { granted ->
                    if (!granted) reply.reject(ARCode.DENIED)
                    else plugin.start(a0, reply)
                }
            }
            "stop" -> {
                plugin.stop(Reply<Unit, ARCode>(settle, null))
            }
            "setImages" -> {
                val a0 = (if (0 < n) r.list { ImageTarget.read(r) } else null) ?: return settle.reject("bad arguments — AR.setImages: images")
                plugin.setImages(a0, Reply<Unit, ARCode>(settle, null))
            }
            "setCodes" -> {
                val a0 = (if (0 < n) r.list { QRTarget.read(r) } else null) ?: return settle.reject("bad arguments — AR.setCodes: codes")
                plugin.setCodes(a0, Reply<Unit, ARCode>(settle, null))
            }
            "hitTest" -> {
                val a0 = (if (0 < n) r.f64() else null) ?: return settle.reject("bad arguments — AR.hitTest: x")
                val a1 = (if (1 < n) r.f64() else null) ?: return settle.reject("bad arguments — AR.hitTest: y")
                val a2 = if (2 < n && !r.isNull()) (HitTarget.read(r) ?: return settle.reject("bad arguments — AR.hitTest: target")) else { if (2 < n) r.skip(); null }
                plugin.hitTest(a0, a1, a2, Reply<List<HitResult>, ARCode>(settle) { v, w ->
                    w.beginArray()
                    for (v1 in v) { v1.write(w) }
                    w.end()
                })
            }
            "anchor" -> {
                val a0 = (if (0 < n) Entity.read(r) else null) ?: return settle.reject("bad arguments — AR.anchor: entity")
                val a1 = (if (1 < n) Pose.read(r) else null) ?: return settle.reject("bad arguments — AR.anchor: pose")
                plugin.anchor(a0, a1, Reply<Unit, ARCode>(settle, null))
            }
            "release" -> {
                val a0 = (if (0 < n) Entity.read(r) else null) ?: return settle.reject("bad arguments — AR.release: entity")
                plugin.release(a0, Reply<Unit, ARCode>(settle, null))
            }
            "captureFrame" -> {
                plugin.captureFrame(Reply<PluginFile, ARCode>(settle) { v, w -> v.write(w) })
            }
            else -> settle.reject("Unknown method: $method")
        }
    }
}
